import { Button, Group, Stack } from '@mantine/core';
import { isEmail, isNotEmpty } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { AddressFields } from './AddressFields';
import { AccountValues, FormProvider, useForm } from './form-context';
import { PersonalFields } from './PersonalFields';

export function FormContextSplit() {
  const form = useForm({
    initialValues: {
      firstName: '',
      lastName: '',
      email: '',
      street: '',
      city: '',
      postalCode: '',
      country: null,
    },
    validate: {
      firstName: isNotEmpty('First name is required'),
      lastName: isNotEmpty('Last name is required'),
      email: isEmail('Invalid email'),
      street: isNotEmpty('Street is required'),
      city: isNotEmpty('City is required'),
      country: isNotEmpty('Country is required'),
    },
  });

  const handleSubmit = (values: AccountValues) => {
    notifications.show({
      title: 'Account created',
      message: `${values.firstName} ${values.lastName} (${values.email}), shipping to ${values.city}, ${values.country}`,
    });
  };

  return (
    <FormProvider form={form}>
      <form onSubmit={form.onSubmit(handleSubmit)}>
        <Stack>
          <PersonalFields />
          <AddressFields />

          <Group justify="flex-end">
            <Button variant="default" onClick={form.reset}>
              Reset
            </Button>

            <Button type="submit">Create account</Button>
          </Group>
        </Stack>
      </form>
    </FormProvider>
  );
}

import { Fieldset, Select, SimpleGrid, Stack, TextInput } from '@mantine/core';
import { useFormContext } from './form-context';

const COUNTRIES = ['United Kingdom', 'United States', 'Germany', 'France', 'Japan'];

export function AddressFields() {
  const form = useFormContext();

  return (
    <Fieldset legend="Shipping address">
      <Stack gap="sm">
        <TextInput
          label="Street"
          placeholder="12 Baker St"
          withAsterisk
          {...form.getInputProps('street')}
        />

        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            label="City"
            placeholder="London"
            withAsterisk
            {...form.getInputProps('city')}
          />

          <TextInput
            label="Postal code"
            placeholder="NW1 6XE"
            {...form.getInputProps('postalCode')}
          />
        </SimpleGrid>

        <Select
          label="Country"
          placeholder="Pick a country"
          data={COUNTRIES}
          withAsterisk
          {...form.getInputProps('country')}
        />
      </Stack>
    </Fieldset>
  );
}

import { Fieldset, SimpleGrid, Stack, TextInput } from '@mantine/core';
import { useFormContext } from './form-context';

export function PersonalFields() {
  const form = useFormContext();

  return (
    <Fieldset legend="Personal information">
